<?php

# @autogenerated
declare(strict_types=1);

use PHPUnit\Framework\TestCase;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\ValueObject\PlatformIdentityRolesVO;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\ValueObject\PlatformIdentityRolesItem;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\ValueObject\PlatformIdentityRolesUidVO;
use Civi\Lughauth\Features\Access\Role\Domain\RoleRef;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\ValueObject\PlatformIdentityRolesListRef;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\ValueObject\PlatformIdentityRolesRoleVO;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\ValueObject\PlatformIdentityRolesVersionVO;

final class PlatformIdentityRolesVOUnitTest extends TestCase
{
    public function test_asignation_keep_value(): void
    {
        $value = new PlatformIdentityRolesListRef(new PlatformIdentityRolesItem(
            PlatformIdentityRolesUidVO::from('one'),
            PlatformIdentityRolesRoleVO::from(new RoleRef('one')),
            PlatformIdentityRolesVersionVO::from(1)
        ));
        $ref = PlatformIdentityRolesVO::from($value);
        $this->assertEquals(new PlatformIdentityRolesListRef(new PlatformIdentityRolesItem(
            PlatformIdentityRolesUidVO::from('one'),
            PlatformIdentityRolesRoleVO::from(new RoleRef('one')),
            PlatformIdentityRolesVersionVO::from(1)
        )), $ref->value());
        $this->assertTrue(!!$ref->find('one'));
        $this->assertTrue(!$ref->find('other'));
        $current = new PlatformIdentityRolesItem(
            PlatformIdentityRolesUidVO::from('one'),
            null,
            null,
        );
        $cloned = PlatformIdentityRolesVO::from([$current]);
        $clonedFilled = $cloned->getWithDefaults($ref);
        $clonedValue = $cloned->value();
        $clonedFilledValue = $clonedFilled->value();
        $this->assertNull($clonedValue->current()->getRole());
        $this->assertEquals(new RoleRef('one'), $clonedFilledValue->current()->getRole());
        $this->assertNull($clonedValue->current()->getVersion());
        $this->assertEquals(1, $clonedFilledValue->current()->getVersion());
        $other = PlatformIdentityRolesVO::tryFrom($ref, new ConstraintFailList());
        $this->assertSame($other, $ref);
        $more = PlatformIdentityRolesVO::from($ref);
        $this->assertSame($more, $ref);
    }
    public function test_asignation_invalid_type(): void
    {
        $errors = new ConstraintFailList();
        $other = PlatformIdentityRolesVO::tryFrom('1', $errors);
        $this->assertNull($other);
        $this->assertTrue($errors->hasErrors());
    }
    public function test_build_empty(): void
    {
        $errors = new ConstraintFailList();
        $temp = PlatformIdentityRolesVO::tryFrom([], $errors);
        $this->assertFalse($temp->value()->valid());
        $temp = PlatformIdentityRolesVO::tryFrom(null, $errors);
        $this->assertNull($temp->value());
    }
}
